  "rankings": [
    {
      "rank": 1,
      "ballot_id": "B007",
      "proposed_laureates": [
        "Harald Rose",
        "Maximilian Haider",
        "Ondrej L. Krivanek"
      ],
      "assessment": {
        "nobel_worthiness": "Aberration correction transformed electron microscopy by enabling sub-ångström imaging and analysis, opening atomic-scale structure and chemistry to direct study. This is a major instrument invention with broad and lasting impact.",
        "attribution": "Rose's optical designs and insight, Haider's realization of practical correctors, and Krivanek's complementary advances in scanning transmission instruments make a strong case for shared recognition. The distinct contributions and priority across the instrument developments need careful historical review.",
        "maturity": "The methods have been in sustained use for decades, with extensive experimental confirmation and major advances in materials research.",
        "uncertainties": [
          "The history of several corrector designs and implementations may make it difficult to define a sufficiently precise discovery and allocate credit among the proposed laureates and other contributors."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B006",
      "proposed_laureates": [
        "Jocelyn Bell Burnell"
      ],
      "assessment": {
        "nobel_worthiness": "The discovery of pulsars revealed a new class of compact astrophysical objects and provided exceptionally precise tests of gravity and dense matter. The result is fundamental and enduring.",
        "attribution": "Bell Burnell identified the unusual radio signals in the observational data and pursued their significance. Recognition should follow the original discovery work, while the broader team's role in building and operating the telescope is acknowledged.",
        "maturity": "Pulsars have been confirmed across many sources and observing methods, and their scientific importance has grown over decades.",
        "uncertainties": [
          "The precise balance between individual discovery credit and the contributions of the wider Cambridge observing team requires careful archival assessment."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B013",
      "proposed_laureates": [
        "Allan H. MacDonald",
        "Pablo Jarillo-Herrero",
        "Rafi Bistritzer"
      ],
      "assessment": {
        "nobel_worthiness": "Magic-angle twisted bilayer graphene created a tunable platform for correlated and topological quantum phases. The emergence of flat bands from moiré structure is a striking and influential discovery in quantum materials.",
        "attribution": "Bistritzer and MacDonald predicted the magic-angle flat-band mechanism; Jarillo-Herrero's group observed superconductivity and correlated insulating behavior. These complementary theoretical and experimental contributions form a coherent case.",
        "maturity": "The central phenomena have been reproduced and the field has expanded to many moiré systems, although the detailed phase diagram and mechanisms remain under active investigation.",
        "uncertainties": [
          "The unsettled microscopic explanations of some phases and the broad, fast-moving follow-on field complicate delimiting the prize-worthy discovery."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B003",
      "proposed_laureates": [
        "Immanuel Bloch",
        "Markus Greiner",
        "Peter Zoller"
      ],
      "assessment": {
        "nobel_worthiness": "Optical-lattice experiments with ultracold atoms made strongly interacting quantum matter controllable and directly observable, including the landmark observation of the Mott-insulator transition. This opened a powerful experimental route into many-body physics.",
        "attribution": "Bloch and Greiner led key experiments that established the platform and its first major results; Zoller contributed foundational theory for quantum simulation with atoms. Cirac's closely related theoretical contributions also merit review.",
        "maturity": "The platform has produced a substantial body of reproducible results and remains productive, though its ability to quantitatively solve important condensed-matter problems is still developing.",
        "uncertainties": [
          "The proposed discovery spans a broad program with multiple experimental and theoretical milestones, making the exact scope and laureate set difficult to fix."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B004",
      "proposed_laureates": [
        "Qi-Kun Xue",
        "Xi Dai",
        "Zhong Fang"
      ],
      "assessment": {
        "nobel_worthiness": "The quantum anomalous Hall effect demonstrates quantized Hall transport without an applied magnetic field and offers a striking realization of topological electronic structure. It is an important fundamental result with potential device relevance.",
        "attribution": "Dai and Fang's theoretical predictions and Xue's experimental realization make a compelling theory-experiment pairing. The contribution of other groups to the magnetic topological-insulator materials and transport work should be checked.",
        "maturity": "The quantized effect has been observed and studied in several material systems, though robust operation at technologically useful temperatures remains challenging.",
        "uncertainties": [
          "The extent to which the original effect and its practical realization can be separated from the broader development of magnetic topological insulators needs historical clarification."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B017",
      "proposed_laureates": [
        "Peter F. Moulton",
        "Ursula Keller",
        "Wilson Sibbett"
      ],
      "assessment": {
        "nobel_worthiness": "The titanium-sapphire laser and passive mode-locking methods made compact, reliable femtosecond solid-state lasers broadly available and helped enable ultrafast science, including later attosecond work.",
        "attribution": "Moulton's titanium-sapphire laser development and Keller's and Sibbett's distinct mode-locking techniques represent important parts of the advance. The scope must distinguish the laser medium from the separate mode-locking inventions.",
        "maturity": "The technology has been established for decades and enabled extensive experimental work across physics and related fields.",
        "uncertainties": [
          "The proposed discovery combines several inventions with different origins, and the division of credit among the nominated contributors and other developers requires careful delimitation."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B064",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks have pushed precision time measurement to a regime that tests fundamental physics and enables new approaches to geodesy and quantum measurement. The advance is both technically profound and broadly consequential.",
        "attribution": "Katori and Ye independently developed leading optical-lattice clock approaches and established their exceptional performance. Their contributions appear appropriate for shared recognition.",
        "maturity": "The precision has been demonstrated and improved across laboratories, though the strongest applications and long-term standards impact continue to develop.",
        "uncertainties": [
          "The field's rapid technical progress makes it important to assess whether the defining achievement is the clock concept, its precision milestones, or a later application."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B020",
      "proposed_laureates": [
        "Ho-kwang (Dave) Mao",
        "Leonid Dubrovinsky",
        "Russell J. Hemley"
      ],
      "assessment": {
        "nobel_worthiness": "Diamond-anvil techniques opened extreme pressures to controlled laboratory study, enabling discoveries about matter under conditions relevant to planetary interiors and high-pressure phases. This is a major experimental capability.",
        "attribution": "Mao and Hemley made seminal contributions to high-pressure diamond-anvil research, while Dubrovinsky advanced techniques and measurements at extreme conditions. The nominated set's distinct roles and priority need careful examination.",
        "maturity": "The methods and their scientific value are firmly established after decades of use, but the proposed contribution represents an extended instrument-development history.",
        "uncertainties": [
          "It is difficult to identify a single bounded invention and a small set of original contributors within the long, collaborative evolution of high-pressure methods."
        ]
      }
    }
  ]
}
